content.arguments:
{"command": "$src = "$env:USERPROFILE\.dsh\sessions\--C-Users-rose-Documents-deepseek-harness-default-workspace--\session-87151d69-dfb9-41cc-882e-c99f2671bf1b\session.v4.jsonl.zstd"
$work = Join-Path $PWD '_session-inspect'
New-Item -ItemType Directory -Force $work | Out-Null
try { Copy-Item $src (Join-Path $work 'snapshot.jsonl.zstd') -Force -ErrorAction Stop; "copied OK" } catch { "copy failed: $($_.Exception.Message)" }
